import pytest

from bedrock_protocol import v898, v1001, v2168

VERSIONS = {"v1001": v1001, "v2168": v2168}

# generated by gophertunnel b8bd735:
# &packet.BookEdit{InventorySlot: 3, ActionType: packet.BookActionReplacePage, PageNumber: 200, Text: "hello",
# PhotoName: "photo.png"}
REPLACE_PAGE = bytes.fromhex("060090030568656c6c6f0970686f746f2e706e67")

# generated by gophertunnel b8bd735:
# &packet.BookEdit{InventorySlot: 3, ActionType: packet.BookActionAddPage, PageNumber: 200, Text: "hello",
# PhotoName: "photo.png"}
ADD_PAGE = bytes.fromhex("060190030568656c6c6f0970686f746f2e706e67")

# generated by gophertunnel b8bd735:
# &packet.BookEdit{InventorySlot: 3, ActionType: packet.BookActionDeletePage, PageNumber: 1}
DELETE_PAGE = bytes.fromhex("060202")

# generated by gophertunnel b8bd735:
# &packet.BookEdit{InventorySlot: 3, ActionType: packet.BookActionSwapPages, PageNumber: 1, SecondaryPageNumber: 2}
SWAP_PAGES = bytes.fromhex("06030204")

# generated by gophertunnel b8bd735:
# &packet.BookEdit{InventorySlot: -1, ActionType: packet.BookActionSign, Title: "Diary", Author: "Steve",
# XUID: "2535465"}
FINALIZE = bytes.fromhex("01040544696172790553746576650732353335343635")

# generated by gophertunnel c8d4e93:
# &packet.BookEdit{ActionType: packet.BookActionReplacePage, InventorySlot: 2, PageNumber: 3, Text: "hi",
# PhotoName: "p"}
V898_REPLACE_PAGE = bytes.fromhex("0002030268690170")

# generated by gophertunnel c8d4e93:
# &packet.BookEdit{ActionType: packet.BookActionDeletePage, InventorySlot: 2, PageNumber: 3}
V898_DELETE_PAGE = bytes.fromhex("020203")

# generated by gophertunnel c8d4e93:
# &packet.BookEdit{ActionType: packet.BookActionSwapPages, InventorySlot: 2, PageNumber: 3, SecondaryPageNumber: 4}
V898_SWAP_PAGES = bytes.fromhex("03020304")

# generated by gophertunnel c8d4e93:
# &packet.BookEdit{ActionType: packet.BookActionSign, InventorySlot: 2, Title: "t", Author: "a", XUID: "x"}
V898_FINALIZE = bytes.fromhex("0402017401610178")

GOLDENS = [
    pytest.param(
        v898.BookEditPacket(
            action=v898.BookEditAction.REPLACE_PAGE, book_slot=2, page_index=3, page_text="hi", photo_name="p"
        ),
        V898_REPLACE_PAGE,
        id="v898-replace-page",
    ),
    pytest.param(
        v898.BookEditPacket(action=v898.BookEditAction.DELETE_PAGE, book_slot=2, page_index=3),
        V898_DELETE_PAGE,
        id="v898-delete-page",
    ),
    pytest.param(
        v898.BookEditPacket(action=v898.BookEditAction.SWAP_PAGES, book_slot=2, page_index=3, swap_with_index=4),
        V898_SWAP_PAGES,
        id="v898-swap-pages",
    ),
    pytest.param(
        v898.BookEditPacket(action=v898.BookEditAction.FINALIZE, book_slot=2, title="t", author="a", xuid="x"),
        V898_FINALIZE,
        id="v898-finalize",
    ),
] + [
    pytest.param(version.BookEditPacket(book_slot=slot, operation=operation), golden, id=f"{name}-{case}")
    for name, version in VERSIONS.items()
    for case, slot, operation, golden in [
        (
            "replace-page",
            3,
            version.ReplacePage(page_index=200, page_text="hello", photo_name="photo.png"),
            REPLACE_PAGE,
        ),
        (
            "add-page",
            3,
            version.AddPage(page_index=200, page_text="hello", photo_name="photo.png"),
            ADD_PAGE,
        ),
        ("delete-page", 3, version.DeletePage(page_index=1), DELETE_PAGE),
        ("swap-pages", 3, version.SwapPages(page_index=1, swap_with_index=2), SWAP_PAGES),
        ("finalize", -1, version.Finalize(title="Diary", author="Steve", xuid="2535465"), FINALIZE),
    ]
]


@pytest.mark.parametrize("version", [v898, v1001, v2168], ids=["v898", "v1001", "v2168"])
def test_book_edit_is_packet_97(version):
    assert version.PACKETS[97] is version.BookEditPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_book_edit_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_book_edit_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_the_add_page_arm_differs_from_replace_page_in_its_case_index_alone():
    assert ADD_PAGE[2:] == REPLACE_PAGE[2:]
    assert ADD_PAGE[:2] != REPLACE_PAGE[:2]


@pytest.mark.parametrize("version", VERSIONS.values(), ids=VERSIONS.keys())
def test_a_truncated_swap_pages_body_is_rejected(version):
    with pytest.raises(ValueError, match="at byte"):
        version.BookEditPacket.from_bytes(SWAP_PAGES[:3])
